    private const FIELDS = ['name', 'short_description', 'description'];

    public function up(): void
    {
        $this->translate();
        $this->concerns();
    }

    /** Takes back only translation rows still holding exactly what this wrote; concern links stay (see below). */
    public function down(): void
    {
        if (! Schema::hasTable('translations') || ! Schema::hasTable('products')) {
            return;
        }

        $ids = DB::table('products')->whereIn('slug', array_keys(self::PRODUCTS))->pluck('id', 'slug');

        foreach (self::PRODUCTS as $slug => $values) {
            foreach ($values as $i => $value) {
                if ($value !== null && isset($ids[$slug])) {
                    DB::table('translations')->where(['locale' => 'ar', 'group' => 'products', 'item_id' => $ids[$slug], 'field' => self::FIELDS[$i], 'value' => $value])->delete();
                }
            }
        }
        // Concern links are not removed: they cannot be told apart from links
        // the owner makes by hand afterwards.
    }

    private function translate(): void
    {
        if (! Schema::hasTable('translations') || ! Schema::hasTable('products')) {
            return;
        }

        $written = 0;
        $skipped = 0;
        $products = DB::table('products')->whereIn('slug', array_keys(self::PRODUCTS))->get(['id', 'slug', 'name', 'short_description', 'description']);

        foreach ($products as $p) {
            foreach (self::PRODUCTS[$p->slug] as $i => $value) {
                if ($value === null || trim((string) $value) === '') {
                    continue;
                }

                $field = self::FIELDS[$i];
                $this->put('products', (int) $p->id, $field, $value, (string) ($p->{$field} ?? '')) ? $written++ : $skipped++;
            }
        }

        if (Schema::hasTable('brands')) {
            foreach (DB::table('brands')->whereIn('name', array_keys(self::BRANDS))->get(['id', 'name']) as $b) {
                $this->put('brands', (int) $b->id, 'name', self::BRANDS[$b->name], (string) $b->name) ? $written++ : $skipped++;
            }
        }

        try {
            if (class_exists(\App\Services\Translation\TranslationStore::class)) {
                \App\Services\Translation\TranslationStore::flush();
            }
        } catch (\Throwable) {
            // The caches expire on their own.
        }

        if (app()->runningInConsole() && ! app()->runningUnitTests()) {
            echo "Arabic product text: {$written} field(s) written, {$skipped} already had Arabic and were left as they are.\n";
        }
    }

    /** ONLY ADDS concern links; a product or concern this shop lacks is skipped. */
    private function concerns(): void
    {
        if (! Schema::hasTable('categories') || ! Schema::hasTable('category_product') || ! Schema::hasTable('products')) {
            return;
        }

        $concernSlugs = array_values(array_unique(array_merge(...array_values(self::CONCERNS))));
        $concerns = DB::table('categories')->whereIn('slug', $concernSlugs)->pluck('id', 'slug')->all();
        $products = DB::table('products')->whereIn('slug', array_keys(self::CONCERNS))->pluck('id', 'slug')->all();

        if ($concerns === [] || $products === []) {
            return;
        }

        $have = [];
        foreach (DB::table('category_product')
            ->whereIn('category_id', array_values($concerns))
            ->whereIn('product_id', array_values($products))
            ->get(['category_id', 'product_id']) as $row) {
            $have[(int) $row->category_id.':'.(int) $row->product_id] = true;
        }

        $rows = [];
        foreach (self::CONCERNS as $productSlug => $wants) {
            if (! isset($products[$productSlug])) {
                continue;
            }

            foreach ($wants as $concernSlug) {
                if (! isset($concerns[$concernSlug])) {
                    continue;
                }

                $key = (int) $concerns[$concernSlug].':'.(int) $products[$productSlug];
                if (isset($have[$key])) {
                    continue;
                }

                $have[$key] = true;
                $rows[] = ['category_id' => (int) $concerns[$concernSlug], 'product_id' => (int) $products[$productSlug]];
            }
        }

        if ($rows === []) {
            return;
        }

        DB::table('category_product')->insertOrIgnore($rows);

        try {
            foreach ([
                'kbb.shop.cats', 'kbb.home.cats', 'kbb.home.rails', 'kbb.cat.rollup.tree',
                'kbb.shop.cats.rollup.include', 'kbb.shop.cats.rollup.own',
                'kbb.home.cats.rollup.include', 'kbb.home.cats.rollup.own',
            ] as $key) {
                Cache::forget($key);
            }
            if (class_exists(\App\Http\Controllers\Store\ShopController::class) && method_exists(\App\Http\Controllers\Store\ShopController::class, 'flushSidebarCache')) {
                \App\Http\Controllers\Store\ShopController::flushSidebarCache();
            }
            if (class_exists(\App\Support\CategoryRollup::class) && method_exists(\App\Support\CategoryRollup::class, 'flush')) {
                \App\Support\CategoryRollup::flush();
            }
        } catch (\Throwable) {
            // A cache that cannot forget expires on its own.
        }

        if (app()->runningInConsole() && ! app()->runningUnitTests()) {
            echo 'Shop by Skin: '.count($rows)." concern link(s) added.\n";
        }
    }

    /** True when written; false when published Arabic was already there. */
    private function put(string $group, int $id, string $field, string $value, string $english): bool
    {
        $key = ['locale' => 'ar', 'group' => $group, 'item_id' => $id, 'field' => $field];
        $row = DB::table('translations')->where($key)->first(['id', 'status', 'value']);

        if ($row !== null && $row->status === 'published' && trim((string) $row->value) !== '') {
            return false;
        }

        $data = ['value' => $value, 'status' => 'published', 'source' => 'manual', 'source_hash' => sha1($english),
            'reviewed_at' => now(), 'updated_at' => now()];

        $row === null
            ? DB::table('translations')->insert($key + $data + ['created_at' => now()])
            : DB::table('translations')->where('id', $row->id)->update($data);

        return true;
    }
